async (state, model) => {
  const excelFile = state.excelFile || 'data.xlsx';
  const prompt = `Use the excel_operations skill to read data from: ${excelFile}\n\nExtract all relevant data including:
- Tables and data ranges
- Charts and visualizations
- Formatting information
- Metadata`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    documentContent: {
      source: excelFile,
      data: result.content.toString(),
      extractedAt: new Date().toISOString()
    },
    messages: [{ role: 'assistant', content: `Excel Data Extracted: ${result.content}` }]
  };
}

async (state, model) => {
  const data = state.documentContent.data || 'No data available';
  const wordFile = state.wordFile || 'document.docx';

  const prompt = `Use the word_operations skill to create a Word document: ${wordFile}\n\nInclude:
1. Title page with metadata
2. Table of contents
3. Data tables from Excel
4. Charts and visualizations
5. Professional formatting and styles

Data to include:\n${data}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    wordFile: wordFile,
    documentContent: {
      ...state.documentContent,
      wordDocument: wordFile,
      wordContent: result.content.toString()
    },
    messages: [{ role: 'assistant', content: `Word Document Generated: ${result.content}` }]
  };
}

async (state, model) => {
  const wordFile = state.wordFile || 'document.docx';
  const pdfFile = state.pdfFile || wordFile.replace('.docx', '.pdf');

  const prompt = `Use the pdf_processing skill to convert Word document to PDF:\nSource: ${wordFile}\nOutput: ${pdfFile}\n\nEnsure:
- All formatting is preserved
- Images and charts are high quality
- Document is optimized for distribution
- Metadata is included`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    pdfFile: pdfFile,
    documentContent: {
      ...state.documentContent,
      pdfDocument: pdfFile,
      conversionComplete: true
    },
    messages: [{ role: 'assistant', content: `PDF Generated: ${result.content}` }]
  };
}
